        ReloadWorkLimit,
        StpWorkLimit,
        LoopWorkLimit,
        FdbWorkLimit,

    """record/replay 按 config 形状选模式：fdb、forward、stp、loop-detect、
    link-forward、link-state、forward-static、forward-stp、forward-check/
    forward-decode（共享 ports,age,max_frame 三键配置，按帧形状区分）、
    stp-check/stp-decode（共享七键配置，按事件帧形状区分）、
    forward-stp-storm、lag、mirror、acl、acl-check、qos、qos-check、
    security-check、mirror-check、lag-check、storm-check 或 port-security。

    events 非 None 时用于区分共享配置形状的两种模式：三键配置的非空帧
    数组含 src（八键）按 forward-check，含 data（t/port/data 原始帧）按
    forward-decode；两种帧形状混用报 InvalidInput；空数组沿用既有
    forward-decode 路由（既有日志字节不变）。stp 七键配置的非链路帧含
    src（九键）按 stp-check，含 data（t/port/data 原始帧）按 stp-decode；
    两种帧形状混用报 InvalidInput；仅链路项或空事件沿用既有 stp-decode
    路由（既有日志字节不变）。
    """
    if isinstance(config, dict):
        keys = frozenset(config)
        # 恰含 ports,age 且 ports 为字符串数组时为 fdb 模式（forward 旧
        # 入口的 ports 为对象数组，形状不重叠）
        if keys == CONFIG_KEYS and isinstance(
            config.get("ports"), list
        ) and all(isinstance(p, str) for p in config["ports"]):
            return "fdb"
        # 恰含 ports,age 且 ports 为非空对象数组时为 forward 模式，旧式
        # access（name/vlan/up）与新式 802.1Q（name/mode/pvid/allowed/
        # untagged/up）两种端口形状均沿用 forward 入口识别与校验
        if (
            keys == CONFIG_KEYS
            and isinstance(config.get("ports"), list)
            and bool(config["ports"])
            and all(isinstance(p, dict) for p in config["ports"])
        ):
            return "forward"
        if keys == STP_CONFIG_KEYS:
            return "stp"
        if keys == LOOP_CONFIG_KEYS:
            return "loop"
        if keys == LINK_FORWARD_CONFIG_KEYS:
            return "link_forward"
        if keys == LINK_STATE_CONFIG_KEYS:
            return "link_state"
        if keys == FORWARD_STATIC_CONFIG_KEYS:
            return "forward_static"
        if keys == FORWARD_STP_CONFIG_KEYS:
            return "forward_stp"
        if keys == FORWARD_CHECK_CONFIG_KEYS:
            # forward-check 与 forward-decode 共享三键配置：非空帧数组含
            # src（八键）按 forward-check，含 data 按 forward-decode，两种
            # 帧形状混用即非法输入；空数组沿用既有 forward-decode 路由
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == FORWARD_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                else:
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "forward_check" if saw_src else "forward_decode"
        if keys == STP_CHECK_CONFIG_KEYS:
            # stp-check 与 stp-decode 共享七键配置：非链路帧含 src 按
            # stp-check，含 data 按 stp-decode，两种帧形状混用即非法输入
            saw_src = False
            saw_data = False
            for event in events if isinstance(events, list) else ():
                if not isinstance(event, dict):
                    raise InvalidInput("bad log event")
                ekeys = frozenset(event)
                if ekeys == STP_CHECK_FRAME_KEYS:
                    saw_src = True
                elif ekeys == FRAME_DECODE_FRAME_KEYS:
                    saw_data = True
                elif ekeys != STP_EVENT_KEYS:
                    raise InvalidInput("bad log event")
            if saw_src and saw_data:
                raise InvalidInput("bad log event")
            return "stp_check" if saw_src else "stp_decode"
        if keys == STORM_CONFIG_KEYS:
            return "forward_stp_storm"
        if keys == LAG_CONFIG_KEYS:
            return "lag"
        if keys == MIRROR_CONFIG_KEYS:
            return "mirror"
        if keys == ACL_CONFIG_KEYS:
            return "acl"
        if keys == ACL_CHECK_CONFIG_KEYS:
            return "acl_check"
        if keys == QOS_CONFIG_KEYS:
            return "qos"
        if keys == QOS_CHECK_CONFIG_KEYS:
            return "qos_check"
        if keys == SECURITY_CHECK_CONFIG_KEYS:
            return "security_check"
        if keys == MIRROR_CHECK_CONFIG_KEYS:
            return "mirror_check"
        if keys == LAG_CHECK_CONFIG_KEYS:
            return "lag_check"
        if keys == STORM_CHECK_CONFIG_KEYS:
            return "storm_check"
    return "security"


def _run_fdb(config, events, observe, max_work=None):
    """record/replay fdb 模式：校验 fdb 配置与事件并执行仿真。

    语义同 fdb 子命令；max_work 非 None 时（record/replay）全量语义校验后
    先按 fdb 公式（逐事件累计 K+1，K 为老化前表项数）以独立空映射无副作用
    预演，首次超过即抛 FdbWorkLimit，不正式仿真。返回 (fdb 结果 dict,
    observer 或 None)；每项 output 恒 None，applied 与 version 由
    _build_log_doc/_verify_records 按 FDB 是否实际改变计算。
    """
    ports, age = validate_config(config)
    fdb_events = validate_events(events, ports)
    if max_work is not None:
        # 与 fdb 入口同一公式：独立空 FDB，无副作用

    entries = []
    for (vlan, mac), (port, seen) in sorted(fdb.items(), key=lambda item: item[0]):
        entries.append(
            {"vlan": vlan, "mac": mac, "port": port, "seen": seen}
        )
    return {"fdb": entries}


def fdb_work(events, age, limit):
    """按既有老化/学习规则用独立空映射无副作用预演并累计工作量。

    逐事件以老化前表项数 K 计 K+1（首事件成本 1，重复源与迁移同样计费）；
    累计等于上限合法，首次超过上限即抛 FdbWorkLimit。
    """
    fdb = {}  # (vlan, mac) -> [port, seen]
    work = 0
    for t, port, mac, vlan in events:
        work += len(fdb) + 1
        if work > limit:
            raise FdbWorkLimit
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        fdb[(vlan, mac)] = [port, t]


def validate_forward_config(config):
    if not isinstance(config, dict) or frozenset(config) != CONFIG_KEYS:
        raise InvalidInput("bad config")
    ports = config["ports"]
    age = config["age"]
    if not isinstance(ports, list) or not ports:
        raise InvalidInput("ports must be a non-empty list")
    names = []
    for port in ports:
        if not isinstance(port, dict) or frozenset(port) != PORT_KEYS:
            raise InvalidInput("bad port")
        name = port["name"]
        vlan = port["vlan"]
        up = port["up"]
        if not isinstance(name, str) or not name:
            raise InvalidInput("bad port name")
        if not _is_int(vlan) or not 1 <= vlan <= 4094:
            raise InvalidInput("bad vlan")
        if not isinstance(up, bool):
            raise InvalidInput("bad up")
        names.append(name)
    if len(set(names)) != len(names):
        raise InvalidInput("ports must be distinct")
    if not _is_int(age) or age <= 0:
        raise InvalidInput("age must be a positive integer")
    return ports, age


def validate_frames(frames, ports):
    if not isinstance(frames, list):
        raise InvalidInput("frames must be a list")
    names = {port["name"] for port in ports}
    result = []
    prev_t = None
    for frame in frames:
        if not isinstance(frame, dict) or frozenset(frame) != FRAME_KEYS:
            raise InvalidInput("bad frame")
        t = frame["t"]
        port = frame["port"]
        src = frame["src"]
        dst = frame["dst"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:
            raise InvalidInput("t not monotonic")
        prev_t = t
        if not isinstance(port, str) or port not in names:
            raise InvalidInput("unknown port")
        if not valid_mac(src):
            raise InvalidInput("bad src")
        if dst != BROADCAST_MAC and not valid_mac(dst):
            raise InvalidInput("bad dst")
        result.append((t, port, src, dst))
    return result


def forward(frames, ports, age):
    by_name = {port["name"]: port for port in ports}
    fdb = {}  # (vlan, mac) -> [port, seen]
    port_stats = {port["name"]: {"rx": 0, "tx": 0, "drop": 0} for port in ports}
    vlan_stats = {}
    for port in ports:
        vlan_stats.setdefault(port["vlan"], {"rx": 0, "tx": 0, "drop": 0})
    results = []
    for t, port_name, src, dst in frames:
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        ingress = by_name[port_name]
        vlan = ingress["vlan"]
        port_stats[port_name]["rx"] += 1
        vlan_stats[vlan]["rx"] += 1
        egress = []
        action = "drop"
        if ingress["up"]:
            fdb[(vlan, src)] = [port_name, t]
            hit = None if dst == BROADCAST_MAC else fdb.get((vlan, dst))
            if hit is not None and hit[0] != port_name:
                egress = [hit[0]]
                action = "unicast"
            elif hit is None:
                egress = [
                    port["name"]
                    for port in ports
                    if port["vlan"] == vlan
                    and port["up"]
                    and port["name"] != port_name
                ]
                if egress:
                    action = "flood"
        for name in egress:
            port_stats[name]["tx"] += 1
            vlan_stats[by_name[name]["vlan"]]["tx"] += 1
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        results.append({"t": t, "action": action, "ports": egress})
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
    }


def _valid_vlan_id(value):
    return _is_int(value) and 1 <= value <= 4094


def _strictly_increasing(values):
    return all(values[i] < values[i + 1] for i in range(len(values) - 1))


def is_v2_config(config):
    if not isinstance(config, dict) or frozenset(config) != CONFIG_KEYS:
        return False
    ports = config["ports"]
    return (
        isinstance(ports, list)
        and bool(ports)
        and all(
            isinstance(port, dict) and frozenset(port) == PORT_KEYS_V2
            for port in ports
        )
    )


def validate_forward_config_v2(config):
    if not isinstance(config, dict) or frozenset(config) != CONFIG_KEYS:
        raise InvalidInput("bad config")
    ports = config["ports"]
    age = config["age"]
    if not isinstance(ports, list) or not ports:
        raise InvalidInput("ports must be a non-empty list")
    names = []
    for port in ports:
        if not isinstance(port, dict) or frozenset(port) != PORT_KEYS_V2:
            raise InvalidInput("bad port")
        name = port["name"]
        mode = port["mode"]
        pvid = port["pvid"]
        allowed = port["allowed"]
        untagged = port["untagged"]
        up = port["up"]
        if not isinstance(name, str) or not name:
            raise InvalidInput("bad port name")
        if mode not in PORT_MODES:
            raise InvalidInput("bad mode")
        if not _valid_vlan_id(pvid):
            raise InvalidInput("bad pvid")
        if (
            not isinstance(allowed, list)
            or not allowed
            or not all(_valid_vlan_id(vlan) for vlan in allowed)
            or not _strictly_increasing(allowed)
            or pvid not in allowed
        ):
            raise InvalidInput("bad allowed")
        if (
            not isinstance(untagged, list)
            or not all(_valid_vlan_id(vlan) for vlan in untagged)
            or not _strictly_increasing(untagged)
            or not all(vlan in allowed for vlan in untagged)
        ):
            raise InvalidInput("bad untagged")
        if not isinstance(up, bool):
            raise InvalidInput("bad up")
        if mode == "access" and (allowed != [pvid] or untagged != [pvid]):
            raise InvalidInput("bad access port")
        if mode == "trunk" and untagged:
            raise InvalidInput("bad trunk port")
        names.append(name)
    if len(set(names)) != len(names):
        raise InvalidInput("ports must be distinct")
    if not _is_int(age) or age <= 0:
        raise InvalidInput("age must be a positive integer")
    return ports, age


def validate_frames_v2(frames, ports):
    if not isinstance(frames, list):
        raise InvalidInput("frames must be a list")
    names = {port["name"] for port in ports}
    result = []
    prev_t = None
    for frame in frames:
        if not isinstance(frame, dict) or frozenset(frame) != FRAME_KEYS_V2:
            raise InvalidInput("bad frame")
        t = frame["t"]
        port = frame["port"]
        src = frame["src"]
        dst = frame["dst"]
        vlan = frame["vlan"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:
            raise InvalidInput("t not monotonic")
        prev_t = t
        if not isinstance(port, str) or port not in names:
            raise InvalidInput("unknown port")
        if not valid_mac(src):
            raise InvalidInput("bad src")
        if dst != BROADCAST_MAC and not valid_mac(dst):
            raise InvalidInput("bad dst")
        if vlan is not None and not _valid_vlan_id(vlan):
            raise InvalidInput("bad vlan")
        result.append((t, port, src, dst, vlan))
    return result


def forward_v2(frames, ports, age):
    by_name = {port["name"]: port for port in ports}
    fdb = {}  # (vlan, mac) -> [port, seen]
    port_stats = {port["name"]: {"rx": 0, "tx": 0, "drop": 0} for port in ports}
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []
    for t, port_name, src, dst, tag in frames:
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        ingress = by_name[port_name]
        port_stats[port_name]["rx"] += 1
        if tag is None:
            vlan = ingress["pvid"]
            rejected = False
        else:
            vlan = tag
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:  # 拒绝帧丢弃且不学习、不计 VLAN
            port_stats[port_name]["drop"] += 1
            results.append({"t": t, "action": "drop", "ports": []})
            continue
        vlan_stats[vlan]["rx"] += 1
        egress = []
        action = "drop"
        if ingress["up"]:
            fdb[(vlan, src)] = [port_name, t]
            hit = None if dst == BROADCAST_MAC else fdb.get((vlan, dst))
            if hit is not None and hit[0] != port_name:
                target = by_name[hit[0]]
                if target["up"] and vlan in target["allowed"]:
                    egress = [hit[0]]
                    action = "unicast"
            elif hit is None:
                egress = [
                    port["name"]
                    for port in ports
                    if vlan in port["allowed"]
                    and port["up"]
                    and port["name"] != port_name
                ]
                if egress:
                    action = "flood"
        out_ports = []
        for name in egress:
            port_stats[name]["tx"] += 1
            vlan_stats[vlan]["tx"] += 1
            out_ports.append(
                {
                    "name": name,
                    "vlan": None if vlan in by_name[name]["untagged"] else vlan,
                }
            )
        if not egress:
            port_stats[port_name]["drop"] += 1
            vlan_stats[vlan]["drop"] += 1
        results.append({"t": t, "action": action, "ports": out_ports})
    return {
        "results": results,
        "ports": [
            {
                "name": port["name"],
                "rx": port_stats[port["name"]]["rx"],
                "tx": port_stats[port["name"]]["tx"],
                "drop": port_stats[port["name"]]["drop"],
            }
            for port in ports
        ],
        "vlans": [
            {
                "vlan": vlan,
                "rx": vlan_stats[vlan]["rx"],
                "tx": vlan_stats[vlan]["tx"],
                "drop": vlan_stats[vlan]["drop"],
            }
            for vlan in sorted(vlan_stats)
        ],
    }


def forward_work(frames, ports, age, limit):
    """旧式 access 转发的工作量预演：独立空 FDB，无副作用。

    P 为配置端口数；逐帧以该帧老化前表项数 K 计 K+P+1（拒绝、down 口、
    重复源及迁移帧均计费），随后按既有规则老化，仅入端口 up 时学习、
    刷新或迁移源 MAC。累计等于上限合法，首次超过即抛 ForwardWorkLimit。
    """
    by_name = {port["name"]: port for port in ports}
    width = len(ports) + 1
    fdb = {}  # (vlan, mac) -> [port, seen]
    work = 0
    for t, port_name, src, dst in frames:
        work += len(fdb) + width
        if work > limit:
            raise ForwardWorkLimit
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        ingress = by_name[port_name]
        if ingress["up"]:
            fdb[(ingress["vlan"], src)] = [port_name, t]


def forward_work_v2(frames, ports, age, limit):
    """新式 802.1Q 转发的工作量预演：独立空 FDB，无副作用。

    计费规则同 forward_work；仅入端口 up 且通过 VLAN 准入时学习、
    刷新或迁移源 MAC。累计等于上限合法，首次超过即抛 ForwardWorkLimit。
    """
    by_name = {port["name"]: port for port in ports}
    width = len(ports) + 1
    fdb = {}  # (vlan, mac) -> [port, seen]
    work = 0
    for t, port_name, src, dst, tag in frames:
        work += len(fdb) + width
        if work > limit:
            raise ForwardWorkLimit
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        ingress = by_name[port_name]
        if tag is None:
            vlan = ingress["pvid"]
            rejected = False
        else:
            vlan = tag
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if not rejected and ingress["up"]:
            fdb[(vlan, src)] = [port_name, t]


def validate_forward_static_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != FORWARD_STATIC_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # ports/age 与新式 forward 同规则
    ports, age = validate_forward_config_v2(
        {"ports": config["ports"], "age": config["age"]}
    )
    static = config["static"]
    if not isinstance(static, list):
        raise InvalidInput("static must be a list")
    by_name = {port["name"]: port for port in ports}
    seen = set()
    result = []
    for entry in static:
        if not isinstance(entry, dict) or frozenset(entry) != STATIC_KEYS:
            raise InvalidInput("bad static entry")
        vlan = entry["vlan"]
        mac = entry["mac"]
        port_name = entry["port"]
        if not _valid_vlan_id(vlan):
            raise InvalidInput("bad static vlan")
        if not valid_mac(mac):  # 小写、非零、单播
            raise InvalidInput("bad static mac")
        if not isinstance(port_name, str) or port_name not in by_name:
            raise InvalidInput("unknown static port")
        if vlan not in by_name[port_name]["allowed"]:
            raise InvalidInput("static vlan not allowed on port")
        if (vlan, mac) in seen:
            raise InvalidInput("duplicate static entry")
        seen.add((vlan, mac))
        result.append((vlan, mac, port_name))
    return ports, age, result

def _build_log_doc(config, events, items):
    """构造 LOG 文档（含 sha256）；records 与事件等长、同序。"""
    if len(events) != len(items):
        raise InvalidInput("bad log")
    mode = _log_mode(config, events)
    records = []
    # version 初值 0，取事件后值；fdb 模式含 port、seen 的表项实际改变
    # （applied）才加 1（同时刻同口幂等重复学习不计），安全模式每次
    # reload/rollback（无变化亦算）加 1，stp/环路模式链路 up 实际改变
    # （applied）才加 1，链路协商
    # 模式仅 applied 链路项加 1（帧项恒 applied 但不计），链路状态模式
    # 仅 applied 项加 1，qos/lag/mirror/acl/security-check/qos-check/
    # acl-check/mirror-check/lag-check/storm-check 模式仅 applied 链路/
    # 成员项加 1（帧与 service 恒 applied 但不计），forward-stp/stp-decode/
    # stp-check/forward-stp-storm 模式仅 applied 链路项加 1（帧项恒
    # applied 但不计），forward-static 模式帧恒 applied 且 version 恒 0
    version = 0
    for event, observed in zip(events, items):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log")
        if mode in ("fdb", "stp", "loop"):
            if observed["applied"]:
                version += 1
        elif mode in (
            "link_forward", "forward_stp", "stp_decode", "stp_check",
            "forward_stp_storm"
        ):
            if kind == "link" and observed["applied"]:
                version += 1
        elif mode == "link_state":
            if observed["applied"]:
                version += 1
        elif mode in (
            "qos", "lag", "mirror", "acl", "security_check", "qos_check",
            "acl_check", "mirror_check", "lag_check", "storm_check"
        ):
            if kind in ("link", "member") and observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        records.append(
            {
                "t": event["t"],
                "version": version,
                "event": _canonical(event),
                "applied": observed["applied"],
                "output": observed["output"],
            }
        )
    doc = {
        "schema": RECORD_SCHEMA,
        "config": _canonical(config),
        "records": records,
    }
    doc["sha256"] = hashlib.sha256(_log_prefix_bytes(doc)).hexdigest()
    return doc


def _log_prefix_bytes(doc):
    """sha256 摘要文本：schema,config,records 规范序列化后含 LF。"""
    prefix = {
        "schema": doc["schema"],
        "config": doc["config"],
        "records": doc["records"],
    }
    return (
